import{_ as o}from"./chunks/home.pc.ko.BuJHOLWU.js";import{_ as a}from"./chunks/hub.pc.ko.D5LMmVxq.js";import{_ as d,o as r,c as e,a5 as n}from"./chunks/framework.BjM_ivYE.js";const b=JSON.parse('{"title":"RBQ 앱","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/gui/introduction.md","filePath":"ko/manual/gui/introduction.md","lastUpdated":1789976009000}'),s={name:"ko/manual/gui/introduction.md"};function i(l,t,h,g,c,p){return r(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="rbq-앱" tabindex="-1">RBQ 앱 <a class="header-anchor" href="#rbq-앱" aria-label="Permalink to &quot;RBQ 앱&quot;">​</a></h1><h2 id="downloads" tabindex="-1">다운로드 <a class="header-anchor" href="#downloads" aria-label="Permalink to &quot;다운로드 {#downloads}&quot;">​</a></h2><p>RBQ 앱은 <strong><a href="/RBQ/ko/manual/downloads/">다운로드</a></strong> 페이지에서 받습니다 — Android 는 Google Play, iPhone · iPad 는 App Store, Linux 데스크탑과 Steam Deck 은 AppImage 입니다.</p><h2 id="앱-소개" tabindex="-1">앱 소개 <a class="header-anchor" href="#앱-소개" aria-label="Permalink to &quot;앱 소개&quot;">​</a></h2><p><strong>RBQ 앱</strong>은 RBQ 4족 보행 로봇을 운용하기 위한 조종 애플리케이션입니다. 로봇에 연결하면 자세 변경(앉기·서기·보행·계단 등), 화면 조이스틱 또는 게임패드 조종, 카메라 영상과 3D 뷰 확인, 배터리·연결·시스템 상태 점검을 할 수 있습니다.</p><p>하나의 앱이 아래 기기에서 동일하게 동작합니다.</p><table tabindex="0"><thead><tr><th>플랫폼</th><th>패키지</th><th>비고</th></tr></thead><tbody><tr><td>Android 태블릿 · 폰</td><td>APK</td><td>터치 조이스틱 사용, 블루투스/USB 게임패드 연결 가능</td></tr><tr><td>iOS (iPad · iPhone)</td><td>App Store / TestFlight 빌드</td><td>MFi 게임패드 지원</td></tr><tr><td>Linux 데스크탑</td><td>AppImage</td><td>키보드·마우스·게임패드 입력</td></tr><tr><td>Steam Deck</td><td>AppImage (게이밍 모드)</td><td>내장 컨트롤러를 게임패드로 사용</td></tr></tbody></table><p><img src="'+o+'" alt="제어 홈"></p><h2 id="주요-화면" tabindex="-1">주요 화면 <a class="header-anchor" href="#주요-화면" aria-label="Permalink to &quot;주요 화면&quot;">​</a></h2><p><img src="'+a+'" alt="허브"></p><p>앱을 켜면 <strong>허브</strong>가 나옵니다. 헤더 왼쪽에는 선택한 로봇의 이름과 연결 상태가 있고(이름을 누르면 로봇 목록이 열립니다), 연결되면 로봇 배터리가 뒤에 붙습니다. 오른쪽에는 프로필 버튼과 앱 설정 톱니 버튼이 있으며, 연결된 동안에는 빨간 <code>E-STOP</code> 버튼이 더해집니다.</p><p>다른 화면도 같은 헤더를 쓰며 왼쪽 위에 <strong>로고</strong>와 <strong>컨트롤</strong> 버튼이 있습니다. 로고는 허브로, <code>컨트롤</code>은 제어 화면으로 갑니다.</p><table tabindex="0"><thead><tr><th>화면</th><th>진입</th><th>용도</th></tr></thead><tbody><tr><td><strong>컨트롤</strong></td><td>허브의 <code>컨트롤</code> 버튼</td><td>실시간 카메라 / 3D 뷰포트, 모션 버튼, 조이스틱, 주행 설정 — <a href="/RBQ/ko/manual/gui/control-home.html">제어 홈</a> 참고. 로봇이 연결됐거나 시뮬을 켠 동안에만 열립니다</td></tr><tr><td><strong>대시보드</strong></td><td><code>대시보드</code> 타일</td><td>모니터링 카드: 시스템, 관절·자세, 구성</td></tr><tr><td><strong>로봇 설정</strong></td><td><code>로봇 설정</code> 타일</td><td>캘리브레이션, 전원 제어, 페이로드 설정, 소프트웨어 업데이트 — <a href="/RBQ/ko/manual/gui/settings.html">설정</a> 참고</td></tr><tr><td><strong>앱 설정</strong></td><td>톱니 버튼</td><td>게임패드, 앱 설정 — <a href="/RBQ/ko/manual/gui/settings.html">설정</a> 참고</td></tr><tr><td><strong>로그</strong></td><td>제어 화면 상단바의 경고 배지 → 목록에서 줄 탭</td><td>실시간 로봇 로그, 시스템 로그, 블랙박스 재생</td></tr></tbody></table><p><code>가이드</code> 타일을 누르면 이 매뉴얼이 열립니다. 로봇 연결과 추가는 로봇 목록에서 합니다 — <a href="/RBQ/ko/manual/gui/connection.html">연결</a> 참고.</p><p>제어 화면 상단바는 좌우 두 덩이입니다. 왼쪽에는 <strong>로고</strong>, 상태 불빛(탭하면 <strong>시스템 종합 상태</strong>가 열립니다), 현재 보행 상태, 신호 세기가 있고, 외부 프로그램이 조종 중이면 <code>SLAM</code> 칩이 함께 뜹니다. 오른쪽에는 경고 개수, <strong>로봇</strong> 배터리, 기기 배터리, 빨간 <code>E-STOP</code> 버튼이 있습니다.</p><h2 id="개발자-모드" tabindex="-1">개발자 모드 <a class="header-anchor" href="#개발자-모드" aria-label="Permalink to &quot;개발자 모드&quot;">​</a></h2><p>앱은 기본적으로 <strong>운용자 등급</strong>으로 동작하며, 이 매뉴얼에서 설명하는 화면은 모두 이 등급에서 열립니다. <strong>개발자 모드</strong>를 켜면 고객사 개발자·통합 담당자를 위한 항목이 추가됩니다 — 추가 모션, 허브의 <strong>정비</strong> 타일, 제어 홈의 카메라 보정과 외부 조종 토글, 설정의 일부 고급 입력칸이 여기에 해당합니다.</p><p>켜려면 오른쪽 위 둥근 버튼으로 프로필 메뉴를 열고 <strong>개발자 모드</strong> 토글을 켠 뒤 암호를 입력합니다. 암호는 Rainbow Robotics 에서 발급하며, 이 매뉴얼에는 적지 않습니다.</p><p><strong>화면마다 무엇이 늘어나는지, 켜고 끄는 방법, 주의할 조작은 <a href="/RBQ/ko/manual/gui/developer-mode.html">개발자 모드</a>에 한곳에 모아 두었습니다.</strong></p>',19)])])}const f=d(s,[["render",i]]);export{b as __pageData,f as default};
